	if sum.Type != "ttl" || sum.Settings != "destroy" || sum.Schedule != "Once" {
		t.Fatalf("ttl: %+v", sum)
	}
	s = apitype.ScheduledAction{ID: "s1", ScheduleOnce: "2026-01-01", Definition: def(apitype.Destroy, true, false)}
	if toScheduleSummary(s).Settings != "destroy + delete stack" {
		t.Fatalf("ttl del: %+v", toScheduleSummary(s))
	}
	// drift
	s = apitype.ScheduledAction{ID: "s2", ScheduleCron: "0 * * * *", Definition: def(apitype.DetectDrift, false, false)}
	sum = toScheduleSummary(s)
	if sum.Type != "drift" || sum.Settings != "detect" || sum.Schedule != "0 * * * *" {
